-- Fixed utility caller profiles;synthetic values only.
DECLARE @ExpectedApiCount int=16;
INSERT @Apis VALUES
(1,N'toolbelt_binary',N'TVF_LeftShiftBigInt','SELECT',N'SELECT * FROM toolbelt_binary.TVF_LeftShiftBigInt(1,63);',N'DECLARE @Rows table(Value bigint NULL); INSERT @Rows SELECT Value FROM toolbelt_binary.TVF_LeftShiftBigInt(1,63); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(bigint,''-9223372036854775808'')) THROW 52097,N''Utility fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value FROM toolbelt_binary.TVF_LeftShiftBigInt(NULL,1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL) THROW 52097,N''Utility NULL oracle.'',13; DELETE @Rows; INSERT @Rows SELECT Value FROM toolbelt_binary.TVF_LeftShiftBigInt(2,-1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=1) THROW 52097,N''Utility reverse shift oracle.'',14; DELETE @Rows; INSERT @Rows SELECT Value FROM toolbelt_binary.TVF_LeftShiftBigInt(1,64); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=0) THROW 52097,N''Utility wide shift oracle.'',15;'),
(2,N'toolbelt_binary',N'TVF_RightShiftBigInt','SELECT',N'SELECT * FROM toolbelt_binary.TVF_RightShiftBigInt(-1,63);',N'DECLARE @Rows table(Value bigint NULL); INSERT @Rows SELECT Value FROM toolbelt_binary.TVF_RightShiftBigInt(-1,63); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=1) THROW 52097,N''Utility fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value FROM toolbelt_binary.TVF_RightShiftBigInt(NULL,1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL) THROW 52097,N''Utility NULL oracle.'',13; '),
(3,N'toolbelt_binary',N'TVF_BitCountBigInt','SELECT',N'SELECT * FROM toolbelt_binary.TVF_BitCountBigInt(-1);',N'DECLARE @Rows table(Value bigint NULL); INSERT @Rows SELECT Value FROM toolbelt_binary.TVF_BitCountBigInt(-1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=64) THROW 52097,N''Utility fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value FROM toolbelt_binary.TVF_BitCountBigInt(NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL) THROW 52097,N''Utility NULL oracle.'',13; '),
(4,N'toolbelt_binary',N'TVF_GetBitBigInt','SELECT',N'SELECT * FROM toolbelt_binary.TVF_GetBitBigInt(-1,63);',N'DECLARE @Rows table(Value bit NULL,IsValid bit NULL,ValidationCode tinyint NULL); INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_binary.TVF_GetBitBigInt(-1,63); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=1 AND IsValid=1 AND ValidationCode=0) THROW 52097,N''Utility fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_binary.TVF_GetBitBigInt(NULL,0); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid IS NULL AND ValidationCode IS NULL) THROW 52097,N''Utility NULL oracle.'',13; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_binary.TVF_GetBitBigInt(0,64); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid=0 AND ValidationCode=10) THROW 52097,N''Utility offset oracle.'',16;'),
(5,N'toolbelt_binary',N'TVF_SetBitBigInt','SELECT',N'SELECT * FROM toolbelt_binary.TVF_SetBitBigInt(0,63,1);',N'DECLARE @Rows table(Value bigint NULL,IsValid bit NULL,ValidationCode tinyint NULL); INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_binary.TVF_SetBitBigInt(0,63,1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value=CONVERT(bigint,''-9223372036854775808'') AND IsValid=1 AND ValidationCode=0) THROW 52097,N''Utility fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_binary.TVF_SetBitBigInt(NULL,0,1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid IS NULL AND ValidationCode IS NULL) THROW 52097,N''Utility NULL oracle.'',13; DELETE @Rows; INSERT @Rows SELECT Value,IsValid,ValidationCode FROM toolbelt_binary.TVF_SetBitBigInt(0,0,2); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND IsValid=0 AND ValidationCode=11) THROW 52097,N''Utility bit value oracle.'',17;'),
(6,N'toolbelt_string',N'TVF_TrimDirectionalNvarchar','SELECT',N'SELECT * FROM toolbelt_string.TVF_TrimDirectionalNvarchar(N''..Contoso..'',N''.'',''BOTH'');',N'DECLARE @Rows table(Value nvarchar(max) NULL); INSERT @Rows SELECT Value FROM toolbelt_string.TVF_TrimDirectionalNvarchar(N''..Contoso..'',N''.'',''BOTH''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(Value)=DATALENGTH(N''Contoso'') AND CONVERT(varbinary(max),Value)=CONVERT(varbinary(max),N''Contoso'')) THROW 52097,N''Utility fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value FROM toolbelt_string.TVF_TrimDirectionalNvarchar(NULL,N''.'',''BOTH''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL) THROW 52097,N''Utility NULL oracle.'',13; '),
(7,N'toolbelt_string',N'TVF_TrimDirectionalVarchar','SELECT',N'SELECT * FROM toolbelt_string.TVF_TrimDirectionalVarchar(''..Contoso..'',''.'',''BOTH'');',N'DECLARE @Rows table(Value varchar(max) NULL); INSERT @Rows SELECT Value FROM toolbelt_string.TVF_TrimDirectionalVarchar(''..Contoso..'',''.'',''BOTH''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE DATALENGTH(Value)=DATALENGTH(''Contoso'') AND CONVERT(varbinary(max),Value)=CONVERT(varbinary(max),''Contoso'')) THROW 52097,N''Utility fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT Value FROM toolbelt_string.TVF_TrimDirectionalVarchar(NULL,''.'',''BOTH''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL) THROW 52097,N''Utility NULL oracle.'',13; '),
(8,N'toolbelt_string',N'TVF_SplitByCharacters','SELECT',N'SELECT * FROM toolbelt_string.TVF_SplitByCharacters(N''a,,b'',N'','',1);',N'DECLARE @Rows table(Value nvarchar(max) NULL,Ordinal bigint NULL); INSERT @Rows SELECT Value,Ordinal FROM toolbelt_string.TVF_SplitByCharacters(N''a,,b'',N'','',1); IF (SELECT COUNT(*) FROM @Rows)<>3 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=1 AND DATALENGTH(Value)=2 AND CONVERT(varbinary(max),Value)=0x6100) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=2 AND Value IS NOT NULL AND DATALENGTH(Value)=0) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=3 AND DATALENGTH(Value)=2 AND CONVERT(varbinary(max),Value)=0x6200) THROW 52097,N''Utility split rows oracle.'',18; DELETE @Rows; INSERT @Rows SELECT Value,Ordinal FROM toolbelt_string.TVF_SplitByCharacters(NULL,N'','',1); IF EXISTS(SELECT 1 FROM @Rows) THROW 52097,N''Utility split NULL rows oracle.'',23;'),
(9,N'toolbelt_string',N'TVF_SplitByCharactersStatus','SELECT',N'SELECT * FROM toolbelt_string.TVF_SplitByCharactersStatus(N''a,,b'',N'','',1);',N'DECLARE @Rows table(Value nvarchar(max) NULL,Ordinal bigint NULL,Status varchar(16) NULL); INSERT @Rows SELECT Value,Ordinal,Status FROM toolbelt_string.TVF_SplitByCharactersStatus(N''a,,b'',N'','',1); IF (SELECT COUNT(*) FROM @Rows)<>3 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=1 AND DATALENGTH(Value)=2 AND CONVERT(varbinary(max),Value)=0x6100) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=2 AND Value IS NOT NULL AND DATALENGTH(Value)=0) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=3 AND DATALENGTH(Value)=2 AND CONVERT(varbinary(max),Value)=0x6200) THROW 52097,N''Utility split rows oracle.'',18; IF EXISTS(SELECT 1 FROM @Rows WHERE Status IS NULL OR Status<>''OK'') THROW 52097,N''Utility split status oracle.'',19; DELETE @Rows; INSERT @Rows SELECT Value,Ordinal,Status FROM toolbelt_string.TVF_SplitByCharactersStatus(NULL,N'','',1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND Ordinal IS NULL AND Status=''SQL_NULL'') THROW 52097,N''Utility split NULL sentinel oracle.'',20; DELETE @Rows; INSERT @Rows SELECT Value,Ordinal,Status FROM toolbelt_string.TVF_SplitByCharactersStatus(N'''',N'','',0); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND Ordinal IS NULL AND Status=''EMPTY'') THROW 52097,N''Utility split empty sentinel oracle.'',21; DELETE @Rows; INSERT @Rows SELECT Value,Ordinal,Status FROM toolbelt_string.TVF_SplitByCharactersStatus(REPLICATE(CONVERT(nvarchar(max),N''x''),32769),N'','',1); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Value IS NULL AND Ordinal IS NULL AND Status=''LIMIT'') THROW 52097,N''Utility split limit sentinel oracle.'',22;'),
(10,N'toolbelt_metadata',N'TVF_ParseMultipartName','SELECT',N'SELECT * FROM toolbelt_metadata.TVF_ParseMultipartName(N''dbo.[Contoso.Detail]'');',N'DECLARE @Rows table(IsValid bit NULL,ValidationCode varchar(32) NULL,PartCount tinyint NULL,ServerName sysname NULL,DatabaseName sysname NULL,SchemaName sysname NULL,ObjectName sysname NULL,QuotedName nvarchar(1035) NULL); INSERT @Rows SELECT IsValid,ValidationCode,PartCount,ServerName,DatabaseName,SchemaName,ObjectName,QuotedName FROM toolbelt_metadata.TVF_ParseMultipartName(N''dbo.[Contoso.Detail]''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE IsValid=1 AND ValidationCode=''VALID'' AND PartCount=2 AND ServerName IS NULL AND DatabaseName IS NULL AND CONVERT(varbinary(max),SchemaName)=CONVERT(varbinary(max),N''dbo'') AND CONVERT(varbinary(max),ObjectName)=CONVERT(varbinary(max),N''Contoso.Detail'') AND CONVERT(varbinary(max),QuotedName)=CONVERT(varbinary(max),N''[dbo].[Contoso.Detail]'')) THROW 52097,N''Utility fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT IsValid,ValidationCode,PartCount,ServerName,DatabaseName,SchemaName,ObjectName,QuotedName FROM toolbelt_metadata.TVF_ParseMultipartName(NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE IsValid=0 AND ValidationCode=''NULL_INPUT'' AND QuotedName IS NULL) THROW 52097,N''Utility NULL oracle.'',13; DELETE @Rows; INSERT @Rows SELECT IsValid,ValidationCode,PartCount,ServerName,DatabaseName,SchemaName,ObjectName,QuotedName FROM toolbelt_metadata.TVF_ParseMultipartName(N''[unclosed''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE IsValid=0 AND ValidationCode=''UNCLOSED_DELIMITER'' AND QuotedName IS NULL) THROW 52097,N''Utility invalid identifier oracle.'',24;'),
(11,N'toolbelt_metadata',N'SVF_QuoteMultipartName','EXECUTE',N'SELECT toolbelt_metadata.SVF_QuoteMultipartName(N''dbo.[Contoso]]Name]'');',N'DECLARE @V nvarchar(1035)=toolbelt_metadata.SVF_QuoteMultipartName(N''dbo.[Contoso]]Name]''); IF @V IS NULL OR DATALENGTH(@V)<>DATALENGTH(N''[dbo].[Contoso]]Name]'') OR CONVERT(varbinary(max),@V)<>CONVERT(varbinary(max),N''[dbo].[Contoso]]Name]'') THROW 52097,N''Utility quote oracle.'',25; IF toolbelt_metadata.SVF_QuoteMultipartName(NULL) IS NOT NULL OR toolbelt_metadata.SVF_QuoteMultipartName(N''[unclosed'') IS NOT NULL THROW 52097,N''Utility quote invalid oracle.'',26;'),
(12,N'toolbelt_validation',N'TVF_ParseSemanticVersion','SELECT',N'SELECT * FROM toolbelt_validation.TVF_ParseSemanticVersion(''1.2.3-alpha.1+build.7'');',N'DECLARE @Rows table(IsValid bit NULL,ValidationCode varchar(32) NULL,Major varchar(8000) NULL,Minor varchar(8000) NULL,Patch varchar(8000) NULL,PreRelease varchar(8000) NULL,BuildMetadata varchar(8000) NULL,CanonicalVersion varchar(8000) NULL); INSERT @Rows SELECT IsValid,ValidationCode,Major,Minor,Patch,PreRelease,BuildMetadata,CanonicalVersion FROM toolbelt_validation.TVF_ParseSemanticVersion(''1.2.3-alpha.1+build.7''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE IsValid=1 AND ValidationCode=''VALID'' AND Major=''1'' AND Minor=''2'' AND Patch=''3'' AND PreRelease COLLATE Latin1_General_100_BIN2=''alpha.1'' AND BuildMetadata COLLATE Latin1_General_100_BIN2=''build.7'' AND CanonicalVersion COLLATE Latin1_General_100_BIN2=''1.2.3-alpha.1+build.7'') THROW 52097,N''Utility fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT IsValid,ValidationCode,Major,Minor,Patch,PreRelease,BuildMetadata,CanonicalVersion FROM toolbelt_validation.TVF_ParseSemanticVersion(NULL); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE IsValid=0 AND CanonicalVersion IS NULL) THROW 52097,N''Utility NULL oracle.'',13; DELETE @Rows; INSERT @Rows SELECT IsValid,ValidationCode,Major,Minor,Patch,PreRelease,BuildMetadata,CanonicalVersion FROM toolbelt_validation.TVF_ParseSemanticVersion(''1.2''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE IsValid=0 AND CanonicalVersion IS NULL AND ValidationCode<>''VALID'') THROW 52097,N''Utility invalid semver oracle.'',27;'),
(13,N'toolbelt_validation',N'TVF_CompareSemanticVersion','SELECT',N'SELECT * FROM toolbelt_validation.TVF_CompareSemanticVersion(''1.2.3-alpha'',''1.2.3'');',N'DECLARE @Rows table(ComparisonResult smallint NULL); INSERT @Rows SELECT ComparisonResult FROM toolbelt_validation.TVF_CompareSemanticVersion(''1.2.3-alpha'',''1.2.3''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE ComparisonResult=-1) THROW 52097,N''Utility fixed value oracle.'',12; DELETE @Rows; INSERT @Rows SELECT ComparisonResult FROM toolbelt_validation.TVF_CompareSemanticVersion(NULL,''1.2.3''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE ComparisonResult IS NULL) THROW 52097,N''Utility NULL oracle.'',13; DELETE @Rows; INSERT @Rows SELECT ComparisonResult FROM toolbelt_validation.TVF_CompareSemanticVersion(''1.2.3+left'',''1.2.3+right''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE ComparisonResult=0) THROW 52097,N''Utility build comparison oracle.'',28;'),
(14,N'toolbelt_validation',N'TVF_SemanticVersionSortKey','SELECT',N'SELECT * FROM toolbelt_validation.TVF_SemanticVersionSortKey(''1.2.3'');',N'DECLARE @Rows table(Ordinal int NULL,SortKey varbinary(max) NULL); INSERT @Rows SELECT 1,SortKey FROM toolbelt_validation.TVF_SemanticVersionSortKey(''1.2.3-alpha.1''); INSERT @Rows SELECT 2,SortKey FROM toolbelt_validation.TVF_SemanticVersionSortKey(''1.2.3''); INSERT @Rows SELECT 3,SortKey FROM toolbelt_validation.TVF_SemanticVersionSortKey(''1.2.3+build.7''); INSERT @Rows SELECT 4,SortKey FROM toolbelt_validation.TVF_SemanticVersionSortKey(NULL); IF (SELECT COUNT(*) FROM @Rows)<>4 OR NOT EXISTS(SELECT 1 FROM @Rows a JOIN @Rows b ON a.Ordinal=1 AND b.Ordinal=2 WHERE DATALENGTH(a.SortKey)>0 AND a.SortKey<b.SortKey) OR NOT EXISTS(SELECT 1 FROM @Rows a JOIN @Rows b ON a.Ordinal=2 AND b.Ordinal=3 WHERE a.SortKey=b.SortKey AND DATALENGTH(a.SortKey)=DATALENGTH(b.SortKey)) OR NOT EXISTS(SELECT 1 FROM @Rows WHERE Ordinal=4 AND SortKey IS NULL) THROW 52097,N''Utility opaque sort-key oracle.'',29;'),
(15,N'toolbelt_validation',N'SVF_SemanticVersionSortKey','EXECUTE',N'SELECT toolbelt_validation.SVF_SemanticVersionSortKey(''1.2.3'');',N'DECLARE @A varbinary(max)=toolbelt_validation.SVF_SemanticVersionSortKey(''1.2.3-alpha.1''),@B varbinary(max)=toolbelt_validation.SVF_SemanticVersionSortKey(''1.2.3''),@C varbinary(max)=toolbelt_validation.SVF_SemanticVersionSortKey(''1.2.3+build.7''); IF @A IS NULL OR @B IS NULL OR @C IS NULL OR DATALENGTH(@A)=0 OR NOT(@A<@B) OR @B<>@C OR DATALENGTH(@B)<>DATALENGTH(@C) OR toolbelt_validation.SVF_SemanticVersionSortKey(NULL) IS NOT NULL THROW 52097,N''Utility scalar sort-key oracle.'',30;'),
(16,N'toolbelt_validation',N'SVF_CompareSemanticVersion','EXECUTE',N'SELECT toolbelt_validation.SVF_CompareSemanticVersion(''1.2.3-alpha'',''1.2.3'');',N'DECLARE @V smallint=toolbelt_validation.SVF_CompareSemanticVersion(''1.2.3-alpha'',''1.2.3''); IF @V IS NULL OR @V<>-1 THROW 52097,N''Utility scalar compare oracle.'',31; IF toolbelt_validation.SVF_CompareSemanticVersion(NULL,''1.2.3'') IS NOT NULL THROW 52097,N''Utility scalar compare NULL oracle.'',32;');
